import {AlertTriangle,ArrowRight,CheckCircle2,Clock3,UserRoundCheck} from "lucide-react"; import {useNavigate} from "react-router-dom"; import {mockInspections} from "../data/mockData"; import StatusBadge from "../components/StatusBadge";
export default function ReviewQueue(){const navigate=useNavigate();const q=mockInspections.filter(i=>i.status!=="PASSED");return <div className="space-y-6 p-6"><div><p className="text-xs font-semibold uppercase tracking-widest text-navy-700">Human review</p><h1 className="mt-1 text-2xl font-bold text-slate-900">Review Queue</h1><p className="mt-2 text-sm text-slate-500">Cases where automated processing requires officer assessment or additional evidence.</p></div><div className="grid gap-4 md:grid-cols-3">{[["Open cases",q.length],["Conflict cases",q.filter(i=>i.conflicts.length).length],["Evidence gaps",q.filter(i=>i.status==="INSUFFICIENT_EVIDENCE").length]].map(([a,b])=><div key={a} className="card p-5"><p className="text-xs uppercase tracking-wide text-slate-400">{a}</p><p className="mt-2 text-3xl font-bold text-slate-900">{b}</p></div>)}</div><div className="space-y-3">{q.map(i=><div key={i.id} className="card p-5"><div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center"><div className="flex items-start gap-4"><div className={`rounded-md p-3 ${i.conflicts.length?"bg-amber-50 text-amber-700":"bg-red-50 text-red-700"}`}>{i.conflicts.length?<AlertTriangle size={21}/>:<Clock3 size={21}/>}</div><div><div className="flex flex-wrap items-center gap-2"><h2 className="text-sm font-bold text-slate-800">{i.productName}</h2><StatusBadge status={i.status}/></div><p className="mt-1 text-xs text-slate-500">{i.caseNumber} · {i.location}</p><p className="mt-2 max-w-2xl text-xs text-slate-600">{i.notes}</p></div></div><button onClick={()=>navigate(`/inspections/${i.id}`)} className="btn-secondary"><UserRoundCheck size={15}/>Review case<ArrowRight size={14}/></button></div></div>)}{!q.length&&<div className="card p-12 text-center"><CheckCircle2 size={32} className="mx-auto text-emerald-600"/><p className="mt-3 text-sm font-semibold">Review queue is clear</p></div>}</div></div>}