import {ArrowLeft,CheckCircle2,Download,FileArchive,FileImage,ScanText,ShieldCheck} from "lucide-react"; import {Link,useParams} from "react-router-dom"; import {mockInspections} from "../data/mockData";
export default function EvidenceDossier(){const{id}=useParams();const i=mockInspections.find(x=>x.id===id)??mockInspections[0];return <div className="space-y-6 p-6"><div className="flex justify-between"><div className="flex items-start gap-3"><Link to={`/inspections/${i.id}`} className="mt-1 rounded-md p-2 text-slate-500"><ArrowLeft size={18}/></Link><div><p className="text-xs font-semibold uppercase tracking-widest text-navy-700">Evidence management</p><h1 className="mt-1 text-2xl font-bold text-slate-900">Evidence Dossier</h1><p className="mt-1 text-xs text-slate-500">{i.caseNumber} · {i.productName}</p></div></div><button className="btn-secondary"><Download size={16}/>Export dossier</button></div><div className="grid gap-4 md:grid-cols-3">{[["Evidence items",i.images.length+i.ocrFields.length],["Audit events",i.auditTrail.length],["Integrity","Traceable"]].map(([a,b])=><div key={a} className="card p-5"><p className="text-[10px] uppercase tracking-wide text-slate-400">{a}</p><p className="mt-2 text-2xl font-bold text-slate-900">{b}</p></div>)}</div><div className="card overflow-hidden"><div className="border-b border-slate-200 px-5 py-4"><p className="section-title">Evidence chain</p><p className="mt-1 text-xs text-slate-500">Source evidence → observations → checks → officer review.</p></div>{[{title:"Original photographs",icon:FileImage,count:i.images.length},{title:"OCR observations",icon:ScanText,count:i.ocrFields.length},{title:"Rule evaluations",icon:ShieldCheck,count:i.ruleResults.length}].map(g=>{const Icon=g.icon;return <section key={g.title} className="p-5 border-b border-slate-100"><div className="flex items-center gap-2"><Icon size={18} className="text-navy-700"/><h2 className="text-sm font-semibold text-slate-800">{g.title}</h2></div><p className="mt-3 text-xs text-slate-500">{g.count} traceable item(s) linked to this inspection.</p></section>})}</div><div className="rounded-lg border border-navy-200 bg-navy-50 p-5"><div className="flex items-start gap-3"><FileArchive size={19} className="text-navy-700"/><div><p className="text-sm font-semibold text-navy-900">Dossier principle</p><p className="mt-1 text-xs leading-relaxed text-navy-800">Machine-generated observations remain distinguishable from original evidence and officer conclusions.</p></div></div></div></div>}