import {AlertCircle,CheckCircle2,Clock3,FileWarning,Loader2} from "lucide-react";
import type {InspectionStatus,RuleStatus} from "../types";
const styles:Record<string,string>={PASSED:"bg-emerald-50 text-emerald-700 border-emerald-200",PASS:"bg-emerald-50 text-emerald-700 border-emerald-200",MANUAL_REVIEW_REQUIRED:"bg-amber-50 text-amber-700 border-amber-200",MANUAL_REVIEW:"bg-amber-50 text-amber-700 border-amber-200",INSUFFICIENT_EVIDENCE:"bg-red-50 text-red-700 border-red-200",FAIL:"bg-red-50 text-red-700 border-red-200",PROCESSING:"bg-blue-50 text-blue-700 border-blue-200",DRAFT:"bg-slate-50 text-slate-600 border-slate-200",NOT_EVALUATED:"bg-slate-50 text-slate-500 border-slate-200"};
export default function StatusBadge({status,size="sm"}:{status:InspectionStatus|RuleStatus;size?:"sm"|"md"}){const Icon=status==="PASSED"||status==="PASS"?CheckCircle2:status==="MANUAL_REVIEW_REQUIRED"||status==="MANUAL_REVIEW"?AlertCircle:status==="INSUFFICIENT_EVIDENCE"||status==="FAIL"?FileWarning:status==="PROCESSING"?Loader2:Clock3;return <span className={`inline-flex items-center gap-1.5 rounded-full border font-semibold uppercase tracking-wide ${size==="md"?"px-3 py-1.5 text-xs":"px-2 py-1 text-[10px]"} ${styles[status]??styles.DRAFT}`}><Icon size={13} className={status==="PROCESSING"?"animate-spin":""}/>{status.replace(/_/g," ")}</span>}