import type { ReactNode } from "react";
import {ArrowDownRight,ArrowUpRight,Minus} from "lucide-react"; import type {KPI} from "../types";
export default function KPICard({kpi,icon}:{kpi:KPI;icon?:ReactNode}){const Trend=kpi.trendDirection==="up"?ArrowUpRight:kpi.trendDirection==="down"?ArrowDownRight:Minus;return <div className="card p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-medium uppercase tracking-wide text-slate-500">{kpi.label}</p><p className="mt-2 text-3xl font-bold tracking-tight text-slate-900">{kpi.value}</p></div>{icon&&<div className="flex h-10 w-10 items-center justify-center rounded-md bg-navy-50 text-navy-700">{icon}</div>}</div><div className="mt-4 flex items-center justify-between"><span className="text-xs text-slate-500">{kpi.helper}</span>{kpi.trend&&<span className="inline-flex items-center gap-1 text-xs font-semibold text-slate-600"><Trend size={13}/>{kpi.trend}</span>}</div></div>}