import {Check,Circle,Loader2,X} from "lucide-react"; import type {PipelineStep} from "../types";
export default function PipelineStepper({steps}:{steps:PipelineStep[]}){return <div className="card p-5"><div className="mb-5"><p className="section-title">Inspection pipeline</p><p className="mt-1 text-xs text-slate-500">Each stage produces traceable evidence for officer review.</p></div><div className="flex flex-col md:flex-row">{steps.map((s,index)=><div key={s.id} className="flex flex-1 md:flex-col"><div className="flex md:items-center"><div className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full border-2 ${s.status==="completed"?"border-emerald-600 bg-emerald-50 text-emerald-700":s.status==="active"?"border-navy-700 bg-navy-50 text-navy-700":s.status==="failed"?"border-red-500 bg-red-50 text-red-700":"border-slate-300 bg-white text-slate-400"}`}>{s.status==="completed"?<Check size={17}/>:s.status==="active"?<Loader2 size={17} className="animate-spin"/>:s.status==="failed"?<X size={17}/>:<Circle size={12}/>}</div>{index<steps.length-1&&<div className="hidden h-px flex-1 bg-slate-200 md:block"/>}</div><div className="ml-4 pb-6 md:ml-0 md:pr-4 md:pt-3"><p className="text-xs font-semibold text-slate-800">{s.label}</p><p className="mt-1 text-[11px] leading-relaxed text-slate-500">{s.description}</p></div></div>)}</div></div>}