import {ArrowLeft,ArrowRight,Camera,CheckCircle2,FileText,Info,ScanLine,ShieldCheck} from "lucide-react"; import {useState} from "react"; import {useNavigate} from "react-router-dom"; import ImageUploader from "../components/ImageUploader"; import PipelineStepper from "../components/PipelineStepper"; import {createInspection} from "../services/inspectionService";
const initial=[["capture","Evidence capture","Upload package photographs.","active"],["ocr","OCR extraction","Extract label declarations.","pending"],["calibration","Calibration","Establish measurement scale.","pending"],["measurement","Measurement","Generate calibrated observations.","pending"],["rules","Rule evaluation","Run deterministic checks.","pending"],["review","Officer review","Human verification and decision.","pending"]] as const;
export default function NewInspection(){const navigate=useNavigate();const[files,setFiles]=useState<File[]>([]);const[steps,setSteps]=useState(initial);const[processing,setProcessing]=useState(false);const start=async()=>{if(!files.length)return;setProcessing(true);const copy=initial.map(x=>({...x,status:x[0]==="capture"?"completed":"pending"}));setSteps(copy as any);const inspection=await createInspection(files,"Amit Singh");for(let i=1;i<copy.length;i++){copy.forEach((s,j)=>s.status=j<=i?"completed":j===i+1?"active":"pending");setSteps([...copy] as any);await new Promise(r=>setTimeout(r,350))}navigate(`/inspections/${inspection.id}`)};return <div className="space-y-6 p-6"><div className="flex items-center gap-3"><button onClick={()=>navigate(-1)} className="rounded-md p-2 text-slate-500"><ArrowLeft size={18}/></button><div><p className="text-xs font-semibold uppercase tracking-widest text-navy-700">New inspection</p><h1 className="mt-1 text-2xl font-bold text-slate-900">Start package inspection</h1></div></div><PipelineStepper steps={steps.map(([id,label,description,status])=>({id,label,description,status:status as any}))}/><div className="grid gap-6 xl:grid-cols-[1fr_360px]"><div className="space-y-6"><section className="card p-6"><p className="section-title">01 / Evidence capture</p><h2 className="mt-1 text-lg font-semibold text-slate-800">Package photographs</h2><p className="mt-1 text-xs text-slate-500">Capture clear, unobstructed evidence including declarations, MRP, net quantity and calibration reference where required.</p><div className="mt-5"><ImageUploader files={files} onFilesChange={setFiles}/></div></section><section className="card p-6"><div className="mb-5 flex items-start gap-3"><FileText size={18} className="text-navy-700"/><div><h2 className="text-sm font-semibold text-slate-800">Inspection metadata</h2><p className="text-xs text-slate-500">Optional context for the demonstration.</p></div></div><div className="grid gap-4 md:grid-cols-2">{["Product category","Declared pack size","Batch / Lot number","Inspection location"].map(x=><label key={x}><span className="mb-1.5 block text-xs font-medium text-slate-600">{x}</span><input className="input" placeholder={x}/></label>)}</div></section><div className="flex justify-end"><button onClick={start} disabled={!files.length||processing} className="btn-primary disabled:opacity-50">{processing?<><ScanLine size={17} className="animate-pulse"/>Processing...</>:<>Begin analysis<ArrowRight size={17}/></>}</button></div></div><aside className="space-y-4"><div className="card p-5"><div className="flex items-center gap-2"><Camera size={18} className="text-navy-700"/><h3 className="text-sm font-semibold text-slate-800">Recommended evidence</h3></div><ul className="mt-4 space-y-3">{["Front label","Back label / declarations","MRP marking","Batch / date details","Calibration reference","Measurement view"].map(x=><li key={x} className="flex items-center gap-2 text-xs text-slate-600"><CheckCircle2 size={14} className="text-emerald-600"/>{x}</li>)}</ul></div><div className="rounded-lg border border-navy-200 bg-navy-50 p-5"><div className="flex items-start gap-3"><Info size={17} className="text-navy-700"/><p className="text-xs leading-relaxed text-navy-800">Every automated observation should remain linked to source evidence.</p></div></div><div className="rounded-lg border border-emerald-200 bg-emerald-50 p-5"><div className="flex items-center gap-2"><ShieldCheck size={17} className="text-emerald-700"/><p className="text-xs font-semibold text-emerald-800">Officer authority</p></div><p className="mt-2 text-xs text-emerald-700">Final inspection decisions remain with the authorized inspecting officer.</p></div></aside></div></div>}