import {ArrowRight,CalendarDays,MapPin} from "lucide-react"; import {useNavigate} from "react-router-dom"; import type {Inspection} from "../types"; import StatusBadge from "./StatusBadge"; import {formatDate} from "../utils/dateUtils";
export default function InspectionTable({inspections}:{inspections:Inspection[]}){const navigate=useNavigate();return <div className="overflow-hidden rounded-lg border border-slate-200 bg-white shadow-workstation"><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead className="border-b border-slate-200 bg-slate-50"><tr>{["Case / Product","Location","Date","Confidence","Status",""].map((x,i)=><th key={i} className="px-5 py-3 text-[11px] font-semibold uppercase tracking-wide text-slate-500">{x}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{inspections.map(i=><tr key={i.id} className="group hover:bg-slate-50"><td className="px-5 py-4"><p className="font-semibold text-slate-800">{i.productName}</p><p className="mt-1 text-xs text-slate-500">{i.caseNumber}</p><p className="mt-1 text-xs text-slate-400">{i.packSize} · Batch {i.batchNumber}</p></td><td className="px-5 py-4"><div className="flex items-start gap-2 text-xs text-slate-600"><MapPin size={14}/>{i.location}</div></td><td className="px-5 py-4"><div className="flex items-center gap-2 text-xs text-slate-600"><CalendarDays size={14}/>{formatDate(i.createdAt)}</div></td><td className="px-5 py-4"><div className="w-24"><span className="text-[10px] font-semibold text-slate-700">{Math.round(i.overallConfidence*100)}%</span><div className="mt-1 h-1.5 overflow-hidden rounded-full bg-slate-200"><div className="h-full rounded-full bg-navy-700" style={{width:`${i.overallConfidence*100}%`}}/></div></div></td><td className="px-5 py-4"><StatusBadge status={i.status}/></td><td className="px-5 py-4 text-right"><button onClick={()=>navigate(`/inspections/${i.id}`)} className="rounded-md p-2 text-slate-400 hover:bg-navy-50 hover:text-navy-700"><ArrowRight size={17}/></button></td></tr>)}</tbody></table></div></div>}