import {Filter,Plus,Search,SlidersHorizontal} from "lucide-react"; import {Link} from "react-router-dom"; import {useMemo,useState} from "react"; import {mockInspections} from "../data/mockData"; import InspectionTable from "../components/InspectionTable";
export default function Inspections(){const[search,setSearch]=useState("");const[status,setStatus]=useState("ALL");const filtered=useMemo(()=>mockInspections.filter(i=>((i.productName+i.caseNumber+i.batchNumber).toLowerCase().includes(search.toLowerCase()))&&(status==="ALL"||i.status===status)),[search,status]);return <div className="space-y-6 p-6"><div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="text-xs font-semibold uppercase tracking-widest text-navy-700">Case register</p><h1 className="mt-1 text-2xl font-bold text-slate-900">Inspections</h1><p className="mt-2 text-sm text-slate-500">Search, filter and inspect package cases.</p></div><Link to="/inspections/new" className="btn-primary"><Plus size={17}/>New Inspection</Link></div><div className="card p-4"><div className="grid gap-3 md:grid-cols-[1fr_220px_auto]"><div className="relative"><Search size={17} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input className="input pl-9" placeholder="Search product, case or batch..." value={search} onChange={e=>setSearch(e.target.value)}/></div><select className="input" value={status} onChange={e=>setStatus(e.target.value)}><option value="ALL">All statuses</option><option value="PASSED">Passed</option><option value="MANUAL_REVIEW_REQUIRED">Manual review</option><option value="INSUFFICIENT_EVIDENCE">Insufficient evidence</option></select><button className="btn-secondary"><SlidersHorizontal size={16}/>Filters</button></div><div className="mt-3 flex items-center gap-2 text-[10px] text-slate-400"><Filter size={13}/>Showing {filtered.length} cases</div></div><InspectionTable inspections={filtered}/></div>}