import {CheckCircle2,FileImage,UploadCloud,X} from "lucide-react"; import {useRef} from "react";
export default function ImageUploader({files,onFilesChange}:{files:File[];onFilesChange:(files:File[])=>void}){const ref=useRef<HTMLInputElement>(null);const add=(list:FileList|null)=>{if(!list)return;onFilesChange([...files,...Array.from(list).filter(f=>f.type.startsWith("image/"))])};return <div><button type="button" onClick={()=>ref.current?.click()} className="flex min-h-48 w-full flex-col items-center justify-center rounded-lg border-2 border-dashed border-slate-300 bg-slate-50 px-6 py-10 text-center hover:border-navy-400 hover:bg-navy-50"><div className="flex h-12 w-12 items-center justify-center rounded-full bg-white text-navy-700 shadow-sm"><UploadCloud size={24}/></div><p className="mt-4 text-sm font-semibold text-slate-800">Upload inspection photographs</p><p className="mt-1 max-w-md text-xs text-slate-500">Front label, back label, MRP, calibration reference and measurement evidence.</p><span className="mt-4 rounded-md bg-navy-700 px-4 py-2 text-xs font-semibold text-white">Select Images</span></button><input ref={ref} type="file" accept="image/*" multiple className="hidden" onChange={e=>add(e.target.files)}/>{files.length>0&&<div className="mt-4 space-y-2">{files.map((f,i)=><div key={`${f.name}-${i}`} className="flex items-center justify-between rounded-md border border-slate-200 bg-white p-3"><div className="flex min-w-0 items-center gap-3"><FileImage size={20} className="shrink-0 text-navy-700"/><div className="min-w-0"><p className="truncate text-xs font-semibold text-slate-700">{f.name}</p><p className="text-[10px] text-slate-400">{(f.size/1024).toFixed(0)} KB</p></div></div><div className="flex items-center gap-2"><CheckCircle2 size={16} className="text-emerald-600"/><button type="button" onClick={()=>onFilesChange(files.filter((_,j)=>j!==i))} className="rounded p-1 text-slate-400 hover:text-red-600"><X size={16}/></button></div></div>)}</div>}</div>}